#### 3. Plot Generator

```typescript
// plot.ts
interface Plot {
  genre: string;
  ideas: string[];
}

const generatePlotIdeas = async (genre: string): Promise<string[]> => {
  const response = await axios.post('https://api.cohere.ai/generate', {
    prompt: `Generate plot ideas for a ${genre} story.`,
    max_tokens: 100,
  });
  return response.data.generations.map(idea => idea.text);
};
```

